        "explanation": "介系詞 by 後接動名詞（by investing in... / by reducing waste and recycling），用來作方式副詞片語，表達「藉由／透過某種具體行動」來達成前面的目標（reduce carbon emissions / protect our environment）。此外，動詞 help 後方可直接加「原形動詞 protect」（省略 to），使語氣更緊湊有力。",
        "keyPoint": "當 and 連接兩個動名詞放在 by 後方時（by reducing waste and recycling），第二個動詞也必須維持 V-ing 平行結構！",
        "example": "Everyone can <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>help protect</span> our environment <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>by reducing waste and recycling</span>.",
