        "tag": "存在與數量限定詞",
        "title": "疑問句中的限定詞：Do you have any + 複數名詞 / 不可數名詞?",
        "pattern": "Do you have + any + 複數可數名詞 (fresh strawberries) / 不可數名詞?",
        "explanation": "在一般疑問句與否定句中，通常使用限定詞 any（任何、一些）來修飾複數可數名詞（fresh strawberries）或不可數名詞，以開放的態度詢問對方是否有存貨；而 some 則多用於肯定句，或「期待對方回答 Yes 的邀請／提供問句（如 Would you like some coffee?）」。",
        "keyPoint": "詢問庫存是否有貨：Do you have any + 複數名詞?（可數名詞別忘了加複數 -s/-ies）。",
