        "explanation": "多形容詞並列修飾同一名詞時（A dark, quiet, and cool room），形容詞之間以逗號及 and 連接。動詞 helps 後接受詞 you，其受詞補語直接用原形動詞片語 fall asleep（入睡，其中 fall 為連綴動詞「進入某狀態」，後接表語形容詞 asleep），最後以副詞比較級 faster 修飾入睡的速度。",
        "keyPoint": "asleep（睡著的）、awake（醒著的）、alive（活著的）屬於「表語形容詞」，只能放在連綴動詞（be / fall / stay）後面，不可放在名詞前面（不可說 an asleep baby）。",
        "example": "A dark, quiet, and cool room also <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>helps you fall asleep faster</span>.",
