        "keyPoint": "當逗號後方的分詞構句帶有介系詞 by（由…所驅動／造成）時，必選被動的「過去分詞 V-p.p.（driven / fueled / led / caused by）」。",
        "example": "Global financial markets showed signs of robust recovery this quarter, <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>driven by</span> strong consumer spending and stabilizing inflation rates.",
