        "explanation": "thrill 原為及物動詞「使極度興奮／激動」。當主詞是「人或我們（We）」感到無比興奮時，必須使用過去分詞 thrilled（感到十分興奮的），後方再接不定詞 to invite you to... 說明感到興奮的原因或動作（我們非常高興能邀請您參加…）。",
