        "explanation": "在活動議程或流程說明中，A, followed by B 是極為道地的高階句型！逗號後的 followed by a Q&A session 是由非限定關係子句 which will be followed by... 簡化而來的過去分詞片語，字面意思是「（現場展示）後面緊接著被問答環節所跟隨」，中文順譯為「隨後進行的是問答環節」。",
        "keyPoint": "千萬注意順序：A, followed by B 代表「A 先發生，接著才是 B」；而且因為是「A 被 B 跟在後面」，永遠使用過去分詞 followed by（不可寫成 following by）！",
        "example": "There will be a live demonstration, <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>followed by a Q&A session</span> with our lead engineers.",
