        "keyPoint": "RSVP 內含「請（s'il vous plaît）」之意，但在商用英文中常習慣寫為 Please RSVP by + 日期，後方可接 to + 電話/Email。",
        "example": "<span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>Refreshments will be served</span>. Please <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>RSVP by October 10th to secure</span> your spot.",
