        "tag": "被動預期句型",
        "title": "預計於某時恢復運作：It is expected to be + 形容詞 + by + 時間",
        "pattern": "主詞 + is/are expected to + 原形動詞 (be operational) + by + 截止時間",
        "explanation": "expect（預期、預計）的主詞若是事物（It，指代電梯），因為事物是「被人們預計」，必須使用被動語態 is expected to + V（預計將會…）。後方接連綴動詞 be 與形容詞 operational（可正常運作的），並以介系詞 by 5 PM 表示「最遲在下午 5 點前完成」。",
        "keyPoint": "be expected to V ＝ be projected to V ＝ be scheduled to V，為多益通知與新聞報導預告未來進度的三大必考被動結構。",
        "example": "It <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>is expected to be operational</span> again <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>by 5 PM</span> on the same day.",
        "exampleZh": "預計將於當天下午 5 點前恢復正常運作。"
