        "explanation": "此句融合了兩大高階結構：(1) compared to the same period last year 是過去分詞片語後位修飾前面的 15% increase（被拿來與去年同期相比的成長）；(2) 逗號後方的 which is fantastic 為「非限定關係子句」，此處的 which 並非單指 last year，而是代表「前面整句話（營收較去年同期成長 15% 這件事）」，因此後面動詞必用單數 is！",
        "keyPoint": "代表「前面整個主要子句」的非限定關係代名詞，前面必有逗號，且只能用 which（絕對不可用 that 或 what）！",
