        "keyPoint": "多益 Part 5 黃金公式：be 動詞 + 【副詞 (-ly)】 + 過去分詞 (V-p.p.) / 現在分詞 (V-ing)！",
        "example": "This growth <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>was primarily driven by</span> our new marketing campaign in Asia.",
