        "explanation": "面試（interview）是「被舉行／進行」的，因此使用未來被動語態 will be conducted。後接三個關鍵介系詞：(1) via Zoom（透過 Zoom 視訊媒介，等同於 through 或 by means of）、(2) on Thursday, October 22nd（特定某一天必用 on）、(3) at 2 PM（精確鐘點必用 at）。",
        "keyPoint": "時間介系詞金三角：in + 年／月／季；on + 星期／具體日期／特定某天早上（on Thursday morning）；at + 精確幾點幾分（at 2 PM）。",
