        "explanation": "動詞 regret 後接不定詞（to V）與動名詞（V-ing）意思完全不同：(1) regret + to V（很遺憾現在必須做某事，通常後接 inform / tell / announce 用來宣布壞消息）；(2) regret + V-ing（後悔過去曾經做過某事）。此外，子句中 containing the custom microchips 為現在分詞片語，後位修飾前面的 our freight shipment（裝有客製化微晶片的貨運）。",
