        "tag": "複合形容詞與方向介系詞",
        "title": "連字號複合形容詞與車票目的地：two round-trip tickets to Boston",
        "pattern": "數詞 + 連字號複合形容詞 (round-trip / one-way) + 名詞 (tickets) + to + 目的地",
        "explanation": "當兩個字以連字號（-）結合成「複合形容詞（round-trip 往返的／來回的）」放在名詞 tickets 前方作前位修飾時，連字號內的名詞必須維持單數形（複數 -s 只加在最後的核心名詞 tickets 上）。此外，英文中表示「前往某地的車票／機票」，tickets 後方固定搭配方向介系詞 to + 地點（tickets to Boston），接著再用 for this Friday 表示「預訂搭乘的日期」。",
        "keyPoint": "車票介系詞必考區別：tickets to + 目的地（前往波士頓的票）vs. tickets for + 日期／班次／活動（本週五的票、演唱會門票）。",
        "example": "I would like to buy <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>two round-trip tickets to</span> Boston <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>for</span> this Friday.",
        "exampleZh": "我想購買兩張本週五前往波士頓的來回票。"
