        "explanation": "為什麼 available（有空位的、可獲得的）放在名詞 seats 的「後面」而不是前面？在英文語法中，當 -able / -ible 結尾的形容詞（特別是 available、possible）與限定詞 any / some / no + 名詞 連用，且後面還接著特定範圍的介系詞片語（on the 9:30 AM express train）時，習慣放在名詞後方作「後位修飾」。它其實是省略了關係代名詞與 be 動詞的形容詞子句：any seats [that are] available on the 9:30 AM express train，強調「該特定班次當下是否還有空位」。",
        "keyPoint": "交通工具介系詞：可站立行走的大型大眾運輸（火車 on the train、飛機 on the plane、公車 on the bus）一律用介系詞 on！",
        "example": "Do you <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>have any seats available on</span> the 9:30 AM express train?",
