        "title": "推測過去可能已發生某事：Could someone have + 過去分詞 (borrowed)...?",
        "pattern": "Could / Might / May + 主詞 + have + 過去分詞 (V-p.p.) ...?",
        "explanation": "這是英文助動詞極重要的進階文法！當助動詞 could / might / may / must 後面接「原形動詞」時，是對「現在或未來」的推測；但若要對「過去已經發生的動作（剛才是不是已經有人把書借走了？）」進行推測時，助動詞後方必須接「完成式：have + 過去分詞（have borrowed）」。",
        "keyPoint": "助動詞 + have + p.p. 家族：must have p.p.（過去一定做了…）、could/might have p.p.（過去可能做了…）、should have p.p.（過去本該做卻沒做）。",
        "example": "<span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>Could someone have borrowed</span> it already?",
