        "title": "承接前句假設之濃縮條件句：If so, can I place a hold on it?",
        "pattern": "前句提問或推論. + If so (= If that is the case), + 主要子句 / 疑問句",
        "explanation": "If so 是英文會話與閱讀中極為高頻的「替代型條件片語」，其中副詞 so 代替了前一整句的假設內容（= If someone has borrowed it already / 如果是那樣的話）。相對地，若要表達「如果不是那樣的話／若非如此」，則使用 If not。",
        "keyPoint": "片語動詞 place a hold on + 物品（在圖書館指「預約保留被借出的書」；在銀行或飯店則指「暫時凍結／圈存款項」）。",
        "example": "<span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>If so</span>, can I <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>place a hold on</span> it online?",
