        "keyPoint": "主要子句用未來式（will be notified），時間副詞子句用現在式（when the book becomes...），主從時態搭配是多益必考重點。",
        "example": "<span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>How will I be notified when</span> the book <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>becomes available for pickup</span>?",
