        "tag": "疑問詞搭配句尾介系詞",
        "title": "疑問形容詞與被動位置句型：Which parking stall is the vehicle located in?",
        "pattern": "Which + 名詞 (parking stall) + is + 主詞 (the vehicle) + located in?",
        "explanation": "表示「某物位於某處」使用被動狀態片語 be located in + 車位／區域。當我們針對介系詞 in 後方的受詞（哪一個停車格 Which parking stall）造疑問句時，疑問詞片語 Which parking stall 移至句首，而原本與其搭配的介系詞 in 則留在句尾（口語自然寫法：Which parking stall is the vehicle located in?；正式書面語亦可將介系詞前移寫作 In which parking stall is the vehicle located?）。",
        "keyPoint": "絕對不可漏掉句尾的介系詞 in！因為 parking stall 是名詞而非地方副詞（對比 Where is the vehicle located? 才不加 in）。",
        "example": "<span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>Which parking stall is</span> the vehicle <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>located in</span>?",
