        "keyPoint": "片語動詞 drop off（順道送交、放下）當受詞是代名詞 them 時，代名詞必須放在動詞與介系詞/副詞中間：drop them off（不可寫成 drop off them）！",
        "example": "If you have <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>gently used</span> electronics, vintage clothing, or children's books <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>to donate</span>, <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>drop them off</span> at the reception hall before Thursday.",
        "exampleZh": "如果您有保存良好的二手電子產品、古著衣物或童書想捐贈，請於週四前送交至接待大廳。"
