        "keyPoint": "防護與阻止類動詞家族一律配介系詞 from：shield / protect / safeguard A from B（保護 A 免於 B）；prevent / keep / stop A from V-ing（阻止 A 做 B）。",
        "example": "Furthermore, <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>maintaining</span> a three-week safety buffer for critical components <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>will shield</span> our domestic assembly plants <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>from</span> sudden logistical bottlenecks.",
