        "keyPoint": "take note of + N（注意到、關注到…）＝ take notice of + N，為正式書面片語。",
        "example": "Institutional investors have taken note of our transparent environmental disclosures, <span class='font-bold text-[#0071E3] underline decoration-[#0071E3]/60 decoration-2 underline-offset-4'>earning our firm top ratings</span> on major global sustainability indexes.",
